package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	lo, _ := strconv.ParseInt(string(next()), 10, 64)
	hi, _ := strconv.ParseInt(string(next()), 10, 64)
	var answer, a int64 = 0, 1
	// hi >= 1 inside the loop, so hi/5 and hi/3 are floor divisions; dividing first avoids overflow
	for a <= hi {
		v := a
		for v <= hi {
			if v >= lo {
				answer++
			}
			if v > hi/5 {
				break
			}
			v *= 5
		}
		if a > hi/3 {
			break
		}
		a *= 3
	}
	w.WriteString(strconv.FormatInt(answer, 10) + "\n")
}
